// `asDev`: the slice's rules on dev worlds (train-range seeds), so that content checks read no test-split text
async function collect(slice, seeds, opts = {}, { asDev = false, beds = BEDS() } = {}) {
  const def = asDev ? { ...sliceDef(slice), bedSplit: 'dev' } : sliceDef(slice);
  const ctx = { beds, slice: def, contracts: C(), spec: SPEC().spec, pin: REAL().frozen.pin };
  const out = [];
  for await (const r of gen.records(slice, seeds, { wordings: wordingsOf(slice), ...(slice.endsWith('ood') ? { carriers: CARRIERS } : {}), ...opts }, ctx)) out.push(r);
  return out;
}
