// =====================================================================================================================================
// acceptance 1: the I2 tag table
const PROGRAM_24 = { onset: 'origin', root: 'origin', precursor: 'origin', dep: 'relay', soft: 'fallback', bg: 'unrelated', benign: 'unrelated', noise: 'unrelated', sporadic: 'unrelated', chronic: 'unrelated', baseline: 'unrelated',
  decoy: 'unrelated', lookalike: 'unrelated', mention: 'unrelated', 'blip-root': 'unrelated', 'blip-same': 'unrelated', 'blip-other': 'unrelated', deploy: 'unrelated', inject: 'unrelated', mislead: 'unrelated', renew: 'unrelated',
  stray: 'unrelated', echo: null, consequence: null };
test('I2 tag table: the program\'s 24 rows are unchanged, four tags are added, echo, consequence and shadow are excluded with a reason, and a tag outside the table fails closed', () => {
  const lm = C().I2.labelMap;
  assert.equal(Object.keys(PROGRAM_24).length, 24, 'the program\'s table has 24 rows (echo and consequence are rows with no option)');
  for (const [tag, label] of Object.entries(PROGRAM_24)) assert.equal(lm.tags[tag], label, `program row ${tag}`);
  // four tags are added by this group (bed 4.2.0 emits them; the program's inventory predates the bed's second audit pass)
  assert.deepEqual({ collateral: lm.tags.collateral, shadow: lm.tags.shadow, rival: lm.tags.rival, 'blip-rival': lm.tags['blip-rival'] }, { collateral: 'relay', shadow: null, rival: 'unrelated', 'blip-rival': 'unrelated' });
  assert.equal(Object.keys(lm.tags).length, 28);
  assert.deepEqual(Object.keys(lm.excluded).sort(), ['consequence', 'echo', 'shadow']);
  for (const reason of Object.values(lm.excluded)) assert.ok(reason.length > 40);
  assert.equal(lm.unmapped, undefined);
  assert.deepEqual(gen.labelOfTag(C().I2, 'rival', lm.bedVersion), 'unrelated');
  assert.equal(gen.labelOfTag(C().I2, 'echo', lm.bedVersion), null);
  assert.equal(gen.labelOfTag(C().I2, 'consequence', lm.bedVersion), null);
  assert.equal(gen.labelOfTag(C().I2, 'shadow', lm.bedVersion), null);
  assert.throws(() => gen.labelOfTag(C().I2, 'synthetic-unknown-tag', lm.bedVersion), e => e.code === 'LABEL_UNMAPPED');
  assert.throws(() => gen.labelOfTag(C().I2, 'dep', '9.9.9'), e => e.code === 'LABEL_BED_VERSION');
  // the solver's pool table knows every tag of the table (a tag the table lacks would be reported as unknown)
  for (const [, tags] of roles.POOL_RULES) for (const t of tags) assert.ok(t in lm.tags, `pool role names the unknown tag ${t}`);
});

test('I2 tag table: bed VERSION 4.2.0 emits exactly the 28 tags on 300 dev worlds (seeds 401-500 x d3-d5); the generator counts echo, consequence and shadow lines and a synthetic unknown tag fails the build', async t => {
  const { gen: bed, version } = await BED();
  assert.equal(version, C().I2.labelMap.bedVersion);
  const seen = {};
  for (let seed = 401; seed <= 500; seed++) for (const d of [3, 4, 5]) for (const [tag, ids] of Object.entries(bed.build(seed, 'dev', d).truth.idsByTag)) seen[tag] = (seen[tag] ?? 0) + ids.length;
  t.diagnostic(`tags on 300 dev worlds: ${JSON.stringify(Object.fromEntries(Object.entries(seen).sort((a, b) => b[1] - a[1])))}`);
  assert.deepEqual(Object.keys(seen).sort(), Object.keys(C().I2.labelMap.tags).sort(), 'the table holds exactly the tags the bed emits');
  gen.resetStats();
  await collect('train', range(401, 8), { ports: ['I2'] });
  const rows = gen.STATS.rows.I2;
  for (const tag of ['echo', 'consequence', 'shadow']) assert.ok(rows[`excluded-${tag}`] > 0, `${tag} lines are excluded and counted: ${JSON.stringify(rows)}`);
  // a synthetic unknown tag in the bed's truth fails the build (LABEL_UNMAPPED), it is not dropped or defaulted
  const real = BEDS(), patched = { ...real, pin: `${real.pin}|synthetic-tag`, import: async rel => {
    const m = await real.import(rel);
    return rel.endsWith('beds/incident/gen.mjs') ? { ...m, build: (...a) => { const r = m.build(...a); r.truth.idsByTag['zz-unmapped'] = [r.truth.idsByTag.bg[0]]; return r; } } : m;
  } };
  await assert.rejects(() => collect('train', range(401, 2), { ports: ['I2'] }, { beds: patched }), e => e.code === 'LABEL_UNMAPPED');
});

// acceptance 2: masked line-skeleton collisions
const pre = s => s.replace(/\b\d{1,3}(?:\.\d{1,3}){3}(?::\d+)?\b/g, ' {ip} ');
test('I2 collisions: masked line-skeleton collisions are < 1% of groups after the exclusions; the remaining groups carry soft targets in train and are absent from every evaluation file', async t => {
  const B = await BED(), table = C().I2.labelMap.tags, groups = new Map(), withShadow = new Map();
  for (let seed = 401; seed <= 440; seed++) for (const d of [3, 4, 5]) {
    const Wd = WORLD.loadWorld(B, 'dev', d, seed);
    for (const [tag, ids] of Object.entries(Wd.truth.idsByTag)) {
      const lab = table[tag], lab2 = tag === 'shadow' ? 'unrelated' : lab;
      for (const id of ids) {
        if (tag === 'bg' && Number(id.slice(1)) % 4) continue;
        const l = Wd.log.byId.get(id), key = `${skeleton(WORLD.ipMasked(l.message), Wd.masks)}|${l.level}`;
        if (lab) { const e = groups.get(key) ?? new Set(); e.add(lab); groups.set(key, e); }
        if (lab2) { const e = withShadow.get(key) ?? new Set(); e.add(lab2); withShadow.set(key, e); }
      }
    }
  }
  const share = m => [...m.values()].filter(e => e.size > 1).length / m.size;
  t.diagnostic(`groups ${groups.size}, collision groups ${(100 * share(groups)).toFixed(2)}% (shadow mapped to unrelated instead: ${(100 * share(withShadow)).toFixed(2)}%)`);
  assert.ok(groups.size > 5000);
  assert.ok(share(groups) < 0.01, `${(100 * share(groups)).toFixed(2)}% of the groups hold more than one option`);
  assert.ok(share(withShadow) > 0.01, 'mapping shadow lines to unrelated would break the 1% bound: that is why they are excluded');
  // train: a line that fits templates of different options gets a soft target; no evaluation file holds one
  const tr = await collect('train', range(401, 60), { ports: ['I2'] });
  const soft = tr.filter(r => r.meta.collision);
  assert.ok(soft.length > 0);
  for (const r of soft) {
    const q = Object.values(r.questions)[0], sum = Object.values(q.target).reduce((a, b) => a + b, 0);
    assert.ok(Math.abs(sum - 1) < 0.02 && Object.keys(q.target).every(k => k in q.criteria) && Object.values(q.target).filter(v => v > 0).length >= 2, JSON.stringify(q.target));
  }
  gen.resetStats();
  for (const [slice, seeds] of [['calib-in', range(4000, 12)], ['dev-select', range(4500, 12)], ['test-in', range(5000, 12)]]) {
    const recs = await collect(slice, seeds, { ports: ['I2'] }, { asDev: slice !== 'test-in' });
    assert.equal(recs.filter(r => r.meta.collision || Object.values(r.questions)[0].target).length, 0, `${slice} holds no collision row`);
  }
  assert.ok(gen.STATS.dropped.I2['collision-in-evaluation'] > 0, 'collision rows were dropped from the evaluation slices and counted');
});

// acceptance 3: no service name in an I1 or I3 state; a service-handle-only predictor
test('names: no service name from the world\'s name lists appears in any I1 or I3 state; the service key is a handle and a handle-only predictor scores no better than the majority class', async t => {
  const B = await BED();
  const names = new Set();
  for (const r of B.C.ROLES) for (const n of r.names) names.add(n);
  for (const e of Object.values(B.C.EXTERNALS)) for (const n of e.names) names.add(n);
  const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const recs = await collect('train', range(601, 120), { ports: ['I1', 'I3'], share: { long: 0.4, injection: 0.5, unknowable: 0.3 } });
  assert.ok(recs.length > 300, `${recs.length} I1 and I3 states`);
  let checked = 0;
  const byWorld = new Map();
  for (const r of recs) {
    const Wd = WORLD.loadWorld(B, 'dev', r.meta.difficulty, r.meta.seed);
    if (!byWorld.has(r.meta.seed)) {
      const own = [...names, ...Object.keys(Wd.truth.aliasDoc), ...Wd.sys.providers.flatMap(p => [p.name, p.host]), ...Wd.log.lines.map(l => l.source)];
      byWorld.set(r.meta.seed, new RegExp(`(?<![A-Za-z0-9_-])(?:${[...new Set(own)].sort((a, b) => b.length - a.length).map(esc).join('|')})(?![A-Za-z0-9_])`));
    }
    const text = JSON.stringify(r.state), m = byWorld.get(r.meta.seed).exec(text);
    assert.equal(m, null, `${m && m[0]} in ${text.slice(Math.max(0, m?.index - 50), (m?.index ?? 0) + 60)}`);
    assert.match(r.state.service, /^svc-[a-z]+$/);
    checked++;
  }
  // the service key tells nothing: the subject is always the first handle; a predictor of the label from the key alone is the majority class
  const i1 = recs.filter(r => portOf(r) === 'I1' && r.meta.variant === 'clean');
  assert.equal(new Set(i1.map(r => r.state.service)).size, 1);
  const rows = i1.map(r => ({ text: r.state.service, label: labelOf(r) })), half = Math.floor(rows.length / 2);
  const model = trainProbe(rows.slice(0, half), { labels: Object.keys(C().I1.options) }), ev = evaluate(model, rows.slice(half));
  const maj = Math.max(...Object.values(counts(rows.slice(half), r => r.label))) / rows.slice(half).length;
  t.diagnostic(`${checked} states checked; handle-only predictor accuracy ${ev.accuracy.toFixed(3)} against majority ${maj.toFixed(3)} on ${rows.length - half} held-out I1 rows`);
  assert.ok(ev.accuracy <= maj + 0.03, `${ev.accuracy} vs majority ${maj}`);
});

// acceptance 4: token budgets
test('I1 states: <= 8 lines and <= 501 real tokens; the long variant <= 40 lines and <= 2.5K; no whole-window variant exists', async t => {
  const recs = (await TRAIN(150)).filter(r => portOf(r) === 'I1');
  const std = recs.filter(r => r.meta.variant !== 'long'), long = recs.filter(r => r.meta.variant === 'long');
  assert.ok(std.length >= 80 && long.length >= 10, `${std.length} standard and ${long.length} long I1 states`);
  const tok = measureRecords([...std, ...long].map(r => ({ state: r.state, questions: r.questions })), { maxState: 8192 });
  const stdTok = tok.slice(0, std.length).map(x => x.stateTokens), longTok = tok.slice(std.length).map(x => x.stateTokens);
  t.diagnostic(`I1 standard: p50 ${quantile(stdTok, 0.5)} p90 ${quantile(stdTok, 0.9)} max ${Math.max(...stdTok)} (${std.length} states); long: p50 ${quantile(longTok, 0.5)} max ${Math.max(...longTok)} (${long.length}); lines max ${Math.max(...std.map(r => r.state.log_lines.length))} / ${Math.max(...long.map(r => r.state.log_lines.length))}`);
  assert.ok(Math.max(...stdTok) <= 501, `max ${Math.max(...stdTok)}`);
  assert.ok(Math.max(...longTok) <= 2500, `long max ${Math.max(...longTok)}`);
  assert.ok(std.every(r => r.state.log_lines.length <= 8) && long.every(r => r.state.log_lines.length <= 40));
  assert.equal(LINE_BUDGET.I1.lines, 8); assert.equal(LINE_BUDGET.I1long.lines, 40); assert.equal(MAX_LINES, 40);
  // no variant shows a whole service window: even an explicit request for 5,000 lines gives at most 40
  const lots = Array.from({ length: 200 }, (_, i) => `L${String(i + 10).padStart(4, '0')} 2026-03-14T10:0${Math.floor(i / 60)}:${String(i % 60).padStart(2, '0')}Z profile-svc-ab12c INFO GET /v1/profile -> 200 (${i} ms)`).join('\n');
  const task = { ...SYN_TASK, inputs: { ...SYN_TASK.inputs, log: `${lots}\n` } };
  const st = kit.buildState(task, { service: 'profile-svc', from: '2026-03-14T10:00:00Z', to: '2026-03-14T10:59:00Z', maxLines: 5000, maxTokens: 1e9, long: true }, 'I1');
  assert.ok(st.log_lines.length <= 40);
  assert.ok(!recs.some(r => /whole/.test(String(r.meta.variant))));
});

// acceptance 5: port kit
test('port kit: buildState(task) equals the factory state byte for byte on 200 tasks (every port), and the served question equals the trained one', async () => {
  const recs = [...(await TRAIN(100)), ...(await collect('dev-select', range(4500, 25), {}, { asDev: true }))].filter(r => !r.meta.kit.edited);
  const seen = new Set(), picked = [];
  for (const r of recs) { const k = `${portOf(r)}|${r.meta.seed}`; if (!seen.has(k)) { seen.add(k); picked.push(r); } }
  const sample = picked.slice(0, 200);
  assert.equal(sample.length, 200, `${picked.length} unedited tasks`);
  const ports = new Set();
  for (const r of sample) {
    const task = await taskOf(r), { port, slots } = r.meta.kit;
    ports.add(port);
    const state = kit.buildState(task, slots, port);
    assert.equal(JSON.stringify(state), JSON.stringify(r.state), `${port} seed ${r.meta.seed}`);
    assert.equal(renderState(state), renderState(r.state));
    const qid = Object.keys(r.questions)[0], q = r.questions[qid];
    if (r.meta.wordingId === 'Q0') {
      const extra = port === 'X5' ? { assumption: q.instructions.match(/assumes: (.*)\. According/)?.[1] } : port === 'X7' ? { subquestion: gen.X7_SUBQUESTION } : {};
      if (port !== 'X5' && port !== 'X7') {
        const served = kit.questions(port, extra)[port];
        assert.equal(served.instructions, q.instructions.replace(/\n$/, '') === served.instructions ? served.instructions : q.instructions);
        assert.equal(questionOf(served.instructions), questionOf(q.instructions));
      }
    }
  }
  assert.deepEqual([...ports].sort(), ['I1', 'I2', 'I3', 'X1', 'X2', 'X5', 'X7']);
});

