test('second code path: the I2 tag from idsByTag and the service from linesBySvc agree on 200 records', async () => {
  const B = await BED();
  const recs = (await TRAIN(100)).filter(r => portOf(r) === 'I2' && r.meta.variant === 'clean').slice(0, 400);
  const idx = new Map();
  let n = 0, agree = 0;
  for (const r of recs) {
    const Wd = WORLD.loadWorld(B, 'dev', r.meta.difficulty, r.meta.seed), id = r.meta.kit.slots.line;
    if (!idx.has(Wd.worldHash)) {
      // path A: tag by line id from idsByTag; path B: service and tag by line id from linesBySvc
      const a = new Map(); for (const [tag, ids] of Object.entries(Wd.truth.idsByTag)) for (const x of ids) a.set(x, tag);
      const b = new Map(); for (const [svc, arr] of Object.entries(Wd.truth.linesBySvc)) for (const x of arr) b.set(x.id, { svc, tag: x.tag });
      idx.set(Wd.worldHash, { a, b });
    }
    const { a, b } = idx.get(Wd.worldHash), fromA = a.get(id), fromB = b.get(id);
    n++;
    if (fromA === fromB.tag && fromB.svc === r.state.emitting_service && !r.meta.collision && gen.labelOfTag(C().I2, fromA, B.version) === labelOf(r)) agree++;
    else if (r.meta.collision) { assert.equal(fromA, fromB.tag); assert.equal(fromB.svc, r.state.emitting_service); agree++; }
  }
  assert.ok(n >= 200, `${n} records`);
  assert.equal(agree, n, `${agree} of ${n} agree`);
});

