// variants
test('variants: an injection twin differs from its clean twin by one inserted line (plus at most two lines the budget pushes out) and keeps the label; a constructed unknowable replaces class-bearing lines by ordinary requests and carries a soft target; long keeps the class', async t => {
  const recs = await TRAIN(100);
  const inj = recs.filter(r => r.meta.variant === 'injection'), by = new Map(recs.filter(r => r.meta.variant === 'clean' && portOf(r) === 'I1').map(r => [r.meta.pairId, r]));
  assert.ok(inj.length >= 10, `${inj.length} injection rows`);
  let verified = 0, dropped = 0;
  for (const r of inj) {
    const twin = by.get(r.meta.pairId);
    assert.ok(twin, 'every injection row has a clean twin');
    assert.equal(labelOf(r), labelOf(twin));
    const rest = r.state.log_lines.filter(l => !twin.state.log_lines.includes(l)), gone = twin.state.log_lines.filter(l => !r.state.log_lines.includes(l));
    assert.equal(rest.length, 1, 'exactly one line is new');
    assert.ok(gone.length <= 2, `the 8-line / 380-token budget pushes out at most two ordinary lines of the twin (${gone.length})`);
    assert.match(r.meta.edit.insert, /^L9\d+$/, 'the inserted line has an id of its own');
    dropped += gone.length;
    assert.match(rest[0], /root_service|fault_class|override|answer|decided|cite/i);
    assert.notEqual(r.meta.injection.urgedOption, labelOf(r), 'the carrier urges the wrong class');
    verified++;
  }
  const unk = recs.filter(r => r.meta.variant === 'unknowable' && portOf(r) === 'I1');
  assert.ok(unk.length >= 5);
  for (const r of unk) {
    const q = Object.values(r.questions)[0];
    assert.ok(q.target && Object.keys(q.target).length === 9 && Math.abs(Object.values(q.target).reduce((a, b) => a + b, 0) - 1) < 1e-9);
    assert.deepEqual(r.meta.unknowable, ['I1']);
  }
  const constructed = unk.filter(r => r.meta.unknowableKind === 'constructed');
  assert.ok(constructed.length >= 3);
  const B = await BED();
  for (const r of constructed) assert.equal(S1.solve({ state: r.state }, B.sc).reason, 'no-evidence');
  const long = recs.filter(r => r.meta.variant === 'long' && portOf(r) === 'I1');
  assert.ok(long.length >= 5);
  for (const r of long) assert.equal(S1.solve({ state: r.state }, B.sc).label, labelOf(r));
  assert.ok(verified > 0);
  t.diagnostic(`${verified} injection rows; ${dropped} ordinary twin lines pushed out by the line/token budget`);
});

test('X5: both polarities of an assumption differ by one sentence; a presence-matched not_stated removes it; dated, stale and shadow notes (X4) are shown to no other port; absent-system rows stay under 10% of not_stated', async () => {
  const B = await BED(), recs = (await TRAIN(100)).filter(r => portOf(r) === 'X5');
  const nat = recs.filter(r => r.meta.x5.kind === 'natural'), flips = recs.filter(r => r.meta.x5.kind === 'flip'), pm = recs.filter(r => r.meta.x5.kind === 'presence-matched'), absent = recs.filter(r => r.meta.x5.kind === 'absent-system');
  assert.ok(nat.length > 100 && flips.length > 50 && pm.length > 20);
  const notesOf = s => s.source_text.split('Notes and recent changes:\n')[1].split('\n');
  const twinOf = new Map(nat.map(r => [r.meta.pairId, r]));
  for (const f of flips) {
    const n = twinOf.get(f.meta.pairId), a = notesOf(n.state), b = notesOf(f.state);
    assert.equal(a.length, b.length);
    assert.equal(a.filter((x, i) => x !== b[i]).length, 1, 'one decisive sentence changed');
    assert.notEqual(labelOf(n), labelOf(f));
    assert.deepEqual([labelOf(n), labelOf(f)].sort(), ['holds', 'violated']);
    assert.equal(n.questions.X5.instructions.match(/assumes: (.*)\. According/)?.[1] ?? n.questions.X5.instructions, n.questions.X5.instructions.match(/assumes: (.*)\. According/)?.[1] ?? n.questions.X5.instructions);
  }
  for (const r of pm) assert.equal(labelOf(r), 'not_stated');
  assert.ok(absent.length <= 0.1 * (pm.length + absent.length), `${absent.length} absent-system of ${pm.length + absent.length} not_stated`);
  // family-level exclusion: no X5 (or other port) state shows a dated pair, a stale-row note or a shadow note
  const pat = /As of (?:January|February|March|April|May|June|July|August|September)|In (?:January|February|March|April|May|June|July|August|September),|The (?:January|February|March|April|May|June|July|August|September) dependency review|shadow instance|load-test replica|capacity tests|soak-tested|is outdated|no longer calls|dropped its call|stopped using|table still shows|does not talk to/;
  for (const r of recs) for (const n of notesOf(r.state)) if (n && pat.test(n)) assert.equal(lib.classifyNote(B.notes, n.replace(/^- /, '')).kind.startsWith('dated') || /shadow|stale/.test(lib.classifyNote(B.notes, n.replace(/^- /, '')).kind), false, n);
  for (const r of recs) for (const n of notesOf(r.state)) assert.ok(['optional', 'hard', 'provider', 'mixed', 'added'].includes(lib.classifyNote(B.notes, n.replace(/^- /, '')).kind), n);
  assert.ok(ASSUMPTIONS.length >= 4);
});

