test('kit fixture: names, pods, hosts, legacy aliases, addresses and providers become handles; the subject is svc-a; a shadow pod\'s lines are not shown', () => {
  const sys = parseSystem(SYN_SYSTEM);
  assert.deepEqual(sys.names, ['edge-gateway', 'checkout-api', 'profile-svc', 'auth-svc']);
  assert.equal(sys.byName.get('checkout-api').legacy, 'till', 'an old name given only in the notes is an alias');
  assert.equal(sys.legacySource, 'checkout-api');
  assert.deepEqual(sys.shadowPods, ['auth-svc-70ec1']);
  assert.equal(serviceOfSource(sys, 'till'), 'checkout-api');
  assert.equal(serviceOfSource(sys, 'auth-svc-9f3d1'), 'auth-svc');
  const state = kit.buildState(SYN_TASK, { service: 'auth-svc', from: '2026-03-14T10:00:00Z', to: '2026-03-14T10:05:00Z' }, 'I1');
  assert.equal(state.service, 'svc-a');
  assert.ok(state.log_lines.every(l => !l.includes('auth-svc-70ec1') && !l.includes('no space left')), 'the shadow pod is not shown');
  const text = JSON.stringify(state);
  for (const n of REAL_NAMES) assert.ok(!text.includes(n), `${n} in ${text}`);
  assert.ok(/ext-a/.test(text) && /svc-b/.test(text) && /svc-c/.test(text) === false || /svc-c/.test(text));
  assert.match(state.log_lines[0], /^2026-03-14T10:00:05Z svc-a-9f3d1 ERROR connection pool/);
  // I2 keeps canonical names; the line has no line id; calls come from the table
  const i2 = kit.buildState(SYN_TASK, { line: 'L0005' }, 'I2');
  assert.deepEqual(i2, { line: '2026-03-14T10:00:09Z auth-svc-9f3d1 ERROR 429 from api.brindlepay.example while calling 10.1.1.2:8443 for checkout-api', emitting_service: 'auth-svc', calls: [] });
  assert.deepEqual(kit.buildState(SYN_TASK, { line: 'L0004' }, 'I2').calls, ['auth-svc'].slice(0, 0).concat(parseSystem(SYN_SYSTEM).byName.get('checkout-api').calls));
  // the handles are the same function the runtime applies
  const h = applyHandles(sys, ['till said auth-svc.live.internal at 10.1.1.4:8080 is down; people agree'], 'auth-svc');
  assert.equal(h.texts[0], 'svc-b said svc-a at svc-a is down; svc-c agree');
});

test('kit fixture: the token budget keeps an I1 state under 8 lines and its estimate under the budget; triage puts warnings first; a missing service or line is refused', () => {
  const lots = Array.from({ length: 30 }, (_, i) => `L${String(i + 10).padStart(4, '0')} 2026-03-14T10:00:${String(i).padStart(2, '0')}Z auth-svc-9f3d1 WARN connection pool 'hikari-primary' at capacity: in use 64/64, ${80 + i} callers waiting for a free slot in the shared client pool`).join('\n');
  const task = { ...SYN_TASK, inputs: { ...SYN_TASK.inputs, log: `${lots}\n` } };
  const st = kit.buildState(task, { service: 'auth-svc', from: '2026-03-14T10:00:00Z', to: '2026-03-14T10:02:00Z' }, 'I1');
  assert.ok(st.log_lines.length <= 8);
  assert.ok(st.log_lines.reduce((a, l) => a + estimateTokens(l) + 1, 0) <= LINE_BUDGET.I1.tokens);
  const lines = [{ level: 'INFO', id: 1 }, { level: 'WARN', id: 2 }, { level: 'DEBUG', id: 3 }, { level: 'ERROR', id: 4 }, { level: 'INFO', id: 5 }];
  assert.deepEqual(triage(lines, 3).map(l => l.id), [1, 2, 4]);
  assert.throws(() => kit.buildState(SYN_TASK, { service: 'nobody', from: '2026-03-14T10:00:00Z', to: '2026-03-14T10:05:00Z' }, 'I1'), e => e.code === 'KIT_SLOT');
  assert.throws(() => kit.buildState(SYN_TASK, { line: 'L9999' }, 'I2'), e => e.code === 'KIT_SLOT');
  assert.throws(() => kit.buildState(SYN_TASK, { service: 'auth-svc', from: '2026-03-14T11:00:00Z', to: '2026-03-14T11:05:00Z' }, 'I1'), e => e.code === 'KIT_EMPTY');
  const x5 = kit.buildState(SYN_TASK, { edge: { from: 'checkout-api', to: 'auth-svc' }, notes: [0] }, 'X5');
  assert.match(x5.source_text, /treats auth-svc as optional/);
  assert.ok(!/shadow instance/.test(x5.source_text));
});

test('solver fixture: a message fitting one pool is decided; the same text in pools of different options is a collision; an unknown text is unmatched; echo lines are excluded; synonyms are followed', () => {
  const sc = MINI_SC();
  const s = (line, service = 'svc-a') => S2.solve({ state: { line, emitting_service: service, calls: [] } }, sc);
  assert.equal(s('2026-03-14T10:00:05Z svc-a-1f2e3 ERROR TLS handshake from 10.1.1.9 rejected by the client: certificate expired (notAfter 2026-03-14T09:00:00Z)').label, 'origin');
  // the dialect and lexicon of a service do not hide the template
  assert.equal(s('2026-03-14T10:00:05Z svc-a-1f2e3 ERROR TLS handshake from 10.1.1.9 rejected by the client: certificate expired (notAfter 2026-03-14T09:00:00Z)').label, 'origin');
  const col = s('2026-03-14T10:00:05Z svc-a-1f2e3 ERROR write to /data/wal/4 failed: out of disk space');
  assert.equal(col.reason, 'collision');
  assert.deepEqual(col.labels, ['origin', 'unrelated']);
  assert.equal(s('2026-03-14T10:00:05Z svc-a-1f2e3 WARN something nobody wrote a template for').reason, 'unmatched');
  assert.equal(s('2026-03-14T10:00:05Z svc-a-1f2e3 WARN write to /data/scratch failed: no space left on device for the backup verifier').label, 'unrelated');
  assert.equal(s('2026-03-14T10:00:05Z svc-a-1f2e3 WARN disk usage 83% on /data (warning threshold 80%)').label, 'unrelated');
  assert.equal(s('2026-03-14T10:00:05Z svc-a-1f2e3 ERROR timeout calling svc-b after 2400ms').label, 'relay');
  assert.equal(s('2026-03-14T10:00:05Z svc-a-1f2e3 INFO svc-b recovered; fallback no longer used').reason, 'excluded');
  // I1: evidence votes; a lookalike line is no evidence; two classes conflict
  const i1 = lines => S1.solve({ state: { service: 'svc-a', window: 'w', log_lines: lines } }, sc);
  const diskLine = '2026-03-14T10:00:05Z svc-a-1f2e3 ERROR write to /data/wal/4 failed: no space left on device', certLine = '2026-03-14T10:00:06Z svc-a-1f2e3 ERROR TLS handshake from 10.1.1.9 rejected by the client: certificate expired (notAfter 2026-03-14T09:00:00Z)';
  assert.equal(i1([certLine, '2026-03-14T10:00:09Z svc-a-1f2e3 WARN write to /data/scratch failed: no space left on device for the backup verifier']).label, 'certificate_expiry');
  assert.equal(i1(['2026-03-14T10:00:09Z svc-a-1f2e3 WARN write to /data/scratch failed: no space left on device for the backup verifier']).reason, 'no-evidence');
  assert.equal(i1([certLine, '2026-03-14T10:00:09Z svc-a-1f2e3 ERROR lookup api.example: temporary failure in name resolution']).reason, 'conflict');
  assert.equal(i1([diskLine]).reason, 'no-evidence', 'a line that a stray pool also writes is not evidence');
});

