test('build: this generator builds a verified Kev dataset from a frozen bed copy (train, dev-select and test-in files, real token fits, no seed below 401)', async t => {
  // a throwaway repository holding only the incident bed and beds/lib, so the shared drift record of this repository is untouched
  const files = {};
  const take = (dir, rel) => { for (const f of readdirSync(path.join(dir, rel))) { const p = path.join(dir, rel, f); if (statSync(p).isFile() && !/\.test\.mjs$/.test(f)) files[`${rel}/${f}`] = readFileSync(p, 'utf8'); } };
  take(BEDS().dir, 'beds/incident'); take(BEDS().dir, 'beds/lib'); files['beds/CONTRACT.md'] = readFileSync(path.join(BEDS().dir, 'beds/CONTRACT.md'), 'utf8');
  const repo = H.tempBedRepo(files);
  const cfg = () => ({ root: repo, outRoot: H.tempDir('kev-incident-build-'), generators: [GEN_FILE], slices: ['train', 'dev-select', 'test-in'], seeds: { train: range(401, 30), 'dev-select': range(4500, 12), 'test-in': range(5000, 12) }, opts: {}, ...H.emptyHeldout() });
  const build = await buildKev(cfg());
  const m = build.manifest, ports = Object.keys(m.slices.train.perPort);
  t.diagnostic(`build ${build.buildId}: train ${m.slices.train.records} records ${JSON.stringify(Object.fromEntries(ports.map(p => [p, m.slices.train.perPort[p].questions])))}, dev-select ${m.slices['dev-select'].records}, test-in ${m.slices['test-in'].records}; job maxState ${m.jobMaxState}`);
  for (const p of ['I1', 'I2', 'X1', 'X5']) assert.ok(ports.includes(p), p);
  // the build drops what exceeds the job's maxState (the 99.9th percentile of real state tokens, rule 6): at most 0.2% of the records, and only long I1 windows
  const drops = m.slices.train.dropped, misfit = drops['misfit-job-max-state'] ?? {};
  assert.deepEqual(Object.keys(drops).filter(k => !['duplicate', 'state-in-dev-select', 'state-in-test-in', 'misfit-job-max-state'].includes(k)), [], JSON.stringify(drops));
  assert.deepEqual(Object.keys(misfit).filter(p => p !== 'I1'), [], JSON.stringify(misfit));
  assert.ok(Object.values(misfit).reduce((a, b) => a + b, 0) <= Math.ceil(0.002 * m.slices.train.records) + 1, JSON.stringify(misfit));
  assert.ok(verifyBuildDir(build.dir).ok);
  for (const slice of ['train', 'dev-select', 'test-in']) {
    const meta = readFileSync(path.join(build.dir, 'kev', `${slice}.meta.jsonl`), 'utf8').trim().split('\n').map(l => JSON.parse(l).meta);
    assert.ok(meta.length > 0 && meta.every(x => x.seed >= 401 && x.reserved === false), slice);
  }
  const again = await buildKev(cfg());
  assert.equal(again.buildId, build.buildId);
  assert.equal(JSON.stringify(again.manifest), JSON.stringify(m), 'a second build gives a byte-identical manifest');
});

