// seeded defect
test('seeded defect: this file runs alone with node --test and fails on seeded defects (an unmapped tag, a leaked name, a swallowed collision)', { skip: MUTANT_RUN ? 'inside a mutant run' : false, timeout: 10 * 60 * 1000 }, () => {
  // the tests that need no frozen bed (a mutant copy has none)
  const pattern = '^(I2 tag table: the program|kit fixture|solver fixture|splits \\(bed-free\\))';
  const mutants = [
    { name: 'a tag falls out of the table (rival is no longer mapped)', mutations: [{ file: 'spec/ports.json', from: '"rival": "unrelated",', to: '' }] },
    { name: 'the tag lookup fails open on an unknown tag', mutations: [{ file: 'ports/incident.mjs', from: 'export const labelOfTag = (contract, tag, bedVersion) => { const m = mapLabel(contract, tag, { bedVersion });', to: "export const labelOfTag = (contract, tag, bedVersion) => { let m; try { m = mapLabel(contract, tag, { bedVersion }); } catch { m = { label: 'unrelated' }; }" }] },
    { name: 'the I2 solver answers a collision with its first option', mutations: [{ file: 'solve/I2.mjs', from: 'if (labels.size === 1) return', to: 'if (labels.size >= 1) return' }] },
    { name: 'legacy aliases are not resolved, so an old name reaches the model', mutations: [{ file: 'judges/incident.mjs', from: "if (s.legacy) aliases.push({ alias: s.legacy, service: s.name, kind: 'legacy' });", to: '' }] },
    { name: 'a shadow pod\'s lines are shown as the service\'s own', mutations: [{ file: 'judges/incident.mjs', from: ' && !isShadowSource(sys, l.source); });', to: '; });' }] },
    { name: 'the I1 state may hold 30 lines', mutations: [{ file: 'judges/incident.mjs', from: 'I1: { lines: 8, tokens: 380 }', to: 'I1: { lines: 30, tokens: 3800 }' }] },
    { name: 'a lookalike pool counts as evidence of a class', mutations: [{ file: 'solve/incident-roles.mjs', from: "[/^(?:LOOKALIKE|LOOKALIKE_MORE|LOOKALIKE_GEN)\\./, ['lookalike']],", to: "[/^(?:LOOKALIKE|LOOKALIKE_MORE|LOOKALIKE_GEN)\\./, ['onset', 'root']]," }] },
    { name: 'a reserved world is no longer reserved', mutations: [{ file: 'lib/registry.mjs', from: 'seeds: [1, 400]', to: 'seeds: [1, 100]' }] },
  ];
  const r = H.seededDefect({ file: TEST_FILE, pattern, mutants, env: { KEV_DATA_MUTANT_RUN: '1' } });
  assert.equal(r.control.status, 0, r.control.stdout.split('\n').filter(l => /not ok/.test(l)).join('\n'));
  assert.ok(r.control.passed.length >= 5, `${r.control.passed.length} bed-free tests passed in the control run`);
  for (const m of r.mutants) assert.ok(m.failed.length > 0 && m.status !== 0, `mutant "${m.name}" was not caught`);
});
